contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum, address _log) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetLogFile(_log); if (__ESBMC_reverted()) return;
        uint afterLogSetMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(afterMinSum == _minSum && afterLogSetMinSum == afterMinSum);
    }

    receive() external payable {}
}

